<?php

declare(strict_types=1);

namespace Tests\Generated\MyCrud\Payment;

use CodeIgniter\Test\CIUnitTestCase;

/**
 * Structural smoke test generated by myCrudCI4.
 *
 * Verifies that the components required by the architecture are published and
 * loadable through the autoloader. It does not access application data.
 */
final class PaymentStructureTest extends CIUnitTestCase
{
    private const EXPECTED_CLASSES = array (
  0 => 'App\\Models\\PaymentModel',
  1 => 'App\\Controllers\\PaymentController',
  2 => 'App\\Validation\\PaymentRules',
  3 => 'App\\Entities\\PaymentEntity',
  4 => 'App\\Services\\PaymentService',
  5 => 'App\\Controllers\\Api\\V1\\PaymentApiController',
  6 => 'App\\API\\Resources\\PaymentResource',
  7 => 'App\\Validation\\PaymentApiRules',
);

    public function testGeneratedClassesAreAutoloadable(): void
    {
        foreach (self::EXPECTED_CLASSES as $class) {
            $this->assertTrue(
                class_exists($class),
                'Generated class is not autoloadable: ' . $class
            );
        }
    }
}
